import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry matmul_kernel(
    .param .u64 param_A,
    .param .u64 param_B,
    .param .u64 param_C,
    .param .u32 param_n
)
{
    .reg .b32 %r_tid, %r_pid, %r_ng, %r_gs, %r_gid, %r_tmp, %r_fm, %r_gm;
    .reg .b32 %r_bx, %r_by, %r_n, %r_kt, %r_k, %r_buf, %r_nbuf, %r_sA, %r_sB;
    .reg .b32 %r_srow, %r_skc, %r_row, %r_col, %r_sk, %r_sc;
    .reg .b32 %r_saddr, %r_saddrA, %r_saddrB;
    .reg .b32 %r_lane, %r_warp, %r_wr, %r_wc, %r_trow, %r_tcol;
    .reg .b32 %r_row0, %r_col0, %r_grow0, %r_gcol0;
    .reg .b32 %r_ab, %r_bb, %r_ab2, %r_bb2;
    .reg .b64 %rd_A, %rd_B, %rd_C, %rd_off;
    .reg .b64 %rd_Aptr, %rd_Bptr, %rd_Bstep, %rd_addr, %rd_rowstride;
    .reg .f32 %f_a0, %f_a1, %f_a2, %f_a3, %f_a4, %f_a5, %f_a6, %f_a7;
    .reg .f32 %f_b0, %f_b1, %f_b2, %f_b3, %f_b4, %f_b5, %f_b6, %f_b7;
    .reg .f32 %f_pa0, %f_pa1, %f_pa2, %f_pa3;
    .reg .f32 %f_acc0, %f_acc1, %f_acc2, %f_acc3, %f_acc4, %f_acc5, %f_acc6, %f_acc7;
    .reg .f32 %f_acc8, %f_acc9, %f_acc10, %f_acc11, %f_acc12, %f_acc13, %f_acc14, %f_acc15;
    .reg .f32 %f_acc16, %f_acc17, %f_acc18, %f_acc19, %f_acc20, %f_acc21, %f_acc22, %f_acc23;
    .reg .f32 %f_acc24, %f_acc25, %f_acc26, %f_acc27, %f_acc28, %f_acc29, %f_acc30, %f_acc31;
    .reg .f32 %f_acc32, %f_acc33, %f_acc34, %f_acc35, %f_acc36, %f_acc37, %f_acc38, %f_acc39;
    .reg .f32 %f_acc40, %f_acc41, %f_acc42, %f_acc43, %f_acc44, %f_acc45, %f_acc46, %f_acc47;
    .reg .f32 %f_acc48, %f_acc49, %f_acc50, %f_acc51, %f_acc52, %f_acc53, %f_acc54, %f_acc55;
    .reg .f32 %f_acc56, %f_acc57, %f_acc58, %f_acc59, %f_acc60, %f_acc61, %f_acc62, %f_acc63;
    .reg .pred %p1;
    // 128x128 CTA tile, 8-wide K tile, 256 threads (8 warps).
    // NEW: explicit warp-level tiling - the 8 warps are arranged 2x4 and
    // each warp owns a 64x32 sub-tile; within a warp each of the 32
    // threads computes an 8x8 register tile (64 FP32 accumulators).
    // Per K step a thread now loads 16 shared floats (4x ld.shared.v4)
    // feeding 64 FMAs (4 FMA per shared byte instead of 2.67 with the
    // previous flat 8x4 thread map), which removes the shared-memory/L1
    // throughput bottleneck shown by the profiler (memory 80.7% >
    // compute 73.6%). The 128x128 CTA tile also halves global/L2 tile
    // traffic versus the old 64x64 tile.
    // sA[k][r] (A staged transposed) and sB[k][c] use 132-float padded
    // rows (conflict-free v4 fragment loads and conflict-free A staging
    // stores), 2 stages, true software-pipelined double buffering: the
    // next K-tile prefetch (A via one ld.global.v4 into registers for
    // the transposed sA staging, B via one 16B cp.async) is issued right
    // after the stage barrier, BEFORE the 512-FMA body, so global-load
    // latency overlaps a full compute window. The K loop body is a
    // constant-8-trip loop (fully unrolled by ptxas). C uses
    // st.global.v4. Swizzled 1D CTA rasterization in groups of 8
    // row-tiles improves L2 reuse.
    .shared .align 16 .b8 sA[8448];
    .shared .align 16 .b8 sB[8448];
    mov.u32 %r_tid, %tid.x;
    ld.param.u64 %rd_A, [param_A];
    ld.param.u64 %rd_B, [param_B];
    ld.param.u64 %rd_C, [param_C];
    ld.param.u32 %r_n, [param_n];
    // Swizzled CTA rasterization: launch is 1D, remap linear CTA id to
    // (bx, by) in groups of 8 row-tiles to improve L2 reuse of A/B tiles.
    mov.u32 %r_pid, %ctaid.x;
    shr.b32 %r_ng, %r_n, 7;
    shl.b32 %r_gs, %r_ng, 3;
    div.u32 %r_gid, %r_pid, %r_gs;
    rem.u32 %r_tmp, %r_pid, %r_gs;
    shl.b32 %r_fm, %r_gid, 3;
    sub.u32 %r_gm, %r_ng, %r_fm;
    min.u32 %r_gm, %r_gm, 8;
    div.u32 %r_bx, %r_tmp, %r_gm;
    rem.u32 %r_tmp, %r_tmp, %r_gm;
    add.u32 %r_by, %r_fm, %r_tmp;
    shl.b32 %r_bx, %r_bx, 7;
    shl.b32 %r_by, %r_by, 7;
    mov.u32 %r_sA, sA;
    mov.u32 %r_sB, sB;
    // ---- warp-level tiling: warp w (0..7) owns a 64x32 sub-tile ----
    // warp_row = w/4 (0..1), warp_col = w%4 (0..3); within a warp,
    // thread_row = lane/4 (0..7), thread_col = lane%4 (0..3); each
    // thread computes rows row0..row0+7, cols col0..col0+3+4.
    and.b32 %r_lane, %r_tid, 31;
    shr.b32 %r_warp, %r_tid, 5;
    shr.b32 %r_wr, %r_warp, 2;
    and.b32 %r_wc, %r_warp, 3;
    shr.b32 %r_trow, %r_lane, 2;
    and.b32 %r_tcol, %r_lane, 3;
    shl.b32 %r_row0, %r_trow, 3;
    shl.b32 %r_tmp, %r_wr, 6;
    add.u32 %r_row0, %r_row0, %r_tmp;
    shl.b32 %r_col0, %r_tcol, 3;
    shl.b32 %r_tmp, %r_wc, 5;
    add.u32 %r_col0, %r_col0, %r_tmp;
    add.u32 %r_grow0, %r_by, %r_row0;
    add.u32 %r_gcol0, %r_bx, %r_col0;
    shl.b32 %r_ab, %r_row0, 2;
    add.u32 %r_ab, %r_ab, %r_sA;
    shl.b32 %r_bb, %r_col0, 2;
    add.u32 %r_bb, %r_bb, %r_sB;
    mov.f32 %f_acc0, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    mov.f32 %f_acc2, 0f00000000;
    mov.f32 %f_acc3, 0f00000000;
    mov.f32 %f_acc4, 0f00000000;
    mov.f32 %f_acc5, 0f00000000;
    mov.f32 %f_acc6, 0f00000000;
    mov.f32 %f_acc7, 0f00000000;
    mov.f32 %f_acc8, 0f00000000;
    mov.f32 %f_acc9, 0f00000000;
    mov.f32 %f_acc10, 0f00000000;
    mov.f32 %f_acc11, 0f00000000;
    mov.f32 %f_acc12, 0f00000000;
    mov.f32 %f_acc13, 0f00000000;
    mov.f32 %f_acc14, 0f00000000;
    mov.f32 %f_acc15, 0f00000000;
    mov.f32 %f_acc16, 0f00000000;
    mov.f32 %f_acc17, 0f00000000;
    mov.f32 %f_acc18, 0f00000000;
    mov.f32 %f_acc19, 0f00000000;
    mov.f32 %f_acc20, 0f00000000;
    mov.f32 %f_acc21, 0f00000000;
    mov.f32 %f_acc22, 0f00000000;
    mov.f32 %f_acc23, 0f00000000;
    mov.f32 %f_acc24, 0f00000000;
    mov.f32 %f_acc25, 0f00000000;
    mov.f32 %f_acc26, 0f00000000;
    mov.f32 %f_acc27, 0f00000000;
    mov.f32 %f_acc28, 0f00000000;
    mov.f32 %f_acc29, 0f00000000;
    mov.f32 %f_acc30, 0f00000000;
    mov.f32 %f_acc31, 0f00000000;
    mov.f32 %f_acc32, 0f00000000;
    mov.f32 %f_acc33, 0f00000000;
    mov.f32 %f_acc34, 0f00000000;
    mov.f32 %f_acc35, 0f00000000;
    mov.f32 %f_acc36, 0f00000000;
    mov.f32 %f_acc37, 0f00000000;
    mov.f32 %f_acc38, 0f00000000;
    mov.f32 %f_acc39, 0f00000000;
    mov.f32 %f_acc40, 0f00000000;
    mov.f32 %f_acc41, 0f00000000;
    mov.f32 %f_acc42, 0f00000000;
    mov.f32 %f_acc43, 0f00000000;
    mov.f32 %f_acc44, 0f00000000;
    mov.f32 %f_acc45, 0f00000000;
    mov.f32 %f_acc46, 0f00000000;
    mov.f32 %f_acc47, 0f00000000;
    mov.f32 %f_acc48, 0f00000000;
    mov.f32 %f_acc49, 0f00000000;
    mov.f32 %f_acc50, 0f00000000;
    mov.f32 %f_acc51, 0f00000000;
    mov.f32 %f_acc52, 0f00000000;
    mov.f32 %f_acc53, 0f00000000;
    mov.f32 %f_acc54, 0f00000000;
    mov.f32 %f_acc55, 0f00000000;
    mov.f32 %f_acc56, 0f00000000;
    mov.f32 %f_acc57, 0f00000000;
    mov.f32 %f_acc58, 0f00000000;
    mov.f32 %f_acc59, 0f00000000;
    mov.f32 %f_acc60, 0f00000000;
    mov.f32 %f_acc61, 0f00000000;
    mov.f32 %f_acc62, 0f00000000;
    mov.f32 %f_acc63, 0f00000000;
    // ---- precompute per-thread staging bases (256 threads, one slot each) ----
    // A: transposed float4 staging, row tid/2, k-cols (tid%2)*4.
    shr.b32 %r_srow, %r_tid, 1;
    and.b32 %r_skc, %r_tid, 1;
    shl.b32 %r_skc, %r_skc, 2;
    add.u32 %r_row, %r_by, %r_srow;
    mul.lo.u32 %r_tmp, %r_row, %r_n;
    add.u32 %r_tmp, %r_tmp, %r_skc;
    mul.wide.u32 %rd_off, %r_tmp, 4;
    add.u64 %rd_Aptr, %rd_A, %rd_off;
    mul.lo.u32 %r_saddrA, %r_skc, 132;
    add.u32 %r_saddrA, %r_saddrA, %r_srow;
    shl.b32 %r_saddrA, %r_saddrA, 2;
    add.u32 %r_saddrA, %r_saddrA, %r_sA;
    // B: float4 cp.async staging, k-row tid/32, cols (tid%32)*4.
    shr.b32 %r_sk, %r_tid, 5;
    and.b32 %r_sc, %r_tid, 31;
    shl.b32 %r_sc, %r_sc, 2;
    add.u32 %r_col, %r_bx, %r_sc;
    mul.lo.u32 %r_tmp, %r_sk, %r_n;
    add.u32 %r_tmp, %r_tmp, %r_col;
    mul.wide.u32 %rd_off, %r_tmp, 4;
    add.u64 %rd_Bptr, %rd_B, %rd_off;
    mul.lo.u32 %r_saddrB, %r_sk, 132;
    add.u32 %r_saddrB, %r_saddrB, %r_sc;
    shl.b32 %r_saddrB, %r_saddrB, 2;
    add.u32 %r_saddrB, %r_saddrB, %r_sB;
    mov.u32 %r_kt, 0;
    mov.u32 %r_buf, 0;
    mov.u32 %r_nbuf, 4224;
    // K-tile pointer steps: A advances 8 floats (32B) along a row,
    // B advances 8 rows (8*n*4 = n<<5 bytes).
    cvt.u64.u32 %rd_Bstep, %r_n;
    shl.b64 %rd_Bstep, %rd_Bstep, 5;
    // ---- prologue: prefetch K-tile 0 (A into regs, B via cp.async stage 0) ----
    ld.global.nc.v4.f32 {%f_pa0, %f_pa1, %f_pa2, %f_pa3}, [%rd_Aptr];
    add.u64 %rd_Aptr, %rd_Aptr, 32;
    cp.async.cg.shared.global [%r_saddrB], [%rd_Bptr], 16;
    add.u64 %rd_Bptr, %rd_Bptr, %rd_Bstep;
    cp.async.commit_group;
$mm_outer:
    // stage prefetched A registers into the current sA stage (transposed)
    add.u32 %r_saddr, %r_saddrA, %r_buf;
    st.shared.f32 [%r_saddr], %f_pa0;
    st.shared.f32 [%r_saddr+528], %f_pa1;
    st.shared.f32 [%r_saddr+1056], %f_pa2;
    st.shared.f32 [%r_saddr+1584], %f_pa3;
    add.u32 %r_ab2, %r_ab, %r_buf;
    add.u32 %r_bb2, %r_bb, %r_buf;
    // wait for the B cp.async stage; one barrier publishes both stages
    cp.async.wait_group 0;
    bar.sync 0;
    // ---- issue the next K-tile prefetch BEFORE the FMA body: the
    // ---- global-load latency now overlaps the full 512-FMA compute
    // ---- window below instead of stalling between K-tiles.
    add.u32 %r_kt, %r_kt, 8;
    setp.lt.u32 %p1, %r_kt, %r_n;
    @!%p1 bra $mm_compute;
    ld.global.nc.v4.f32 {%f_pa0, %f_pa1, %f_pa2, %f_pa3}, [%rd_Aptr];
    add.u64 %rd_Aptr, %rd_Aptr, 32;
    add.u32 %r_saddr, %r_saddrB, %r_nbuf;
    cp.async.cg.shared.global [%r_saddr], [%rd_Bptr], 16;
    add.u64 %rd_Bptr, %rd_Bptr, %rd_Bstep;
    cp.async.commit_group;
$mm_compute:
    mov.u32 %r_k, 0;
$mm_kloop:
    // ---- 8x8 register-blocked inner product (constant-8-trip K loop) ----
    ld.shared.v4.f32 {%f_a0, %f_a1, %f_a2, %f_a3}, [%r_ab2];
    ld.shared.v4.f32 {%f_a4, %f_a5, %f_a6, %f_a7}, [%r_ab2+16];
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_bb2];
    ld.shared.v4.f32 {%f_b4, %f_b5, %f_b6, %f_b7}, [%r_bb2+16];
    fma.rn.f32 %f_acc0, %f_a0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a0, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc2, %f_a0, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_a0, %f_b3, %f_acc3;
    fma.rn.f32 %f_acc4, %f_a0, %f_b4, %f_acc4;
    fma.rn.f32 %f_acc5, %f_a0, %f_b5, %f_acc5;
    fma.rn.f32 %f_acc6, %f_a0, %f_b6, %f_acc6;
    fma.rn.f32 %f_acc7, %f_a0, %f_b7, %f_acc7;
    fma.rn.f32 %f_acc8, %f_a1, %f_b0, %f_acc8;
    fma.rn.f32 %f_acc9, %f_a1, %f_b1, %f_acc9;
    fma.rn.f32 %f_acc10, %f_a1, %f_b2, %f_acc10;
    fma.rn.f32 %f_acc11, %f_a1, %f_b3, %f_acc11;
    fma.rn.f32 %f_acc12, %f_a1, %f_b4, %f_acc12;
    fma.rn.f32 %f_acc13, %f_a1, %f_b5, %f_acc13;
    fma.rn.f32 %f_acc14, %f_a1, %f_b6, %f_acc14;
    fma.rn.f32 %f_acc15, %f_a1, %f_b7, %f_acc15;
    fma.rn.f32 %f_acc16, %f_a2, %f_b0, %f_acc16;
    fma.rn.f32 %f_acc17, %f_a2, %f_b1, %f_acc17;
    fma.rn.f32 %f_acc18, %f_a2, %f_b2, %f_acc18;
    fma.rn.f32 %f_acc19, %f_a2, %f_b3, %f_acc19;
    fma.rn.f32 %f_acc20, %f_a2, %f_b4, %f_acc20;
    fma.rn.f32 %f_acc21, %f_a2, %f_b5, %f_acc21;
    fma.rn.f32 %f_acc22, %f_a2, %f_b6, %f_acc22;
    fma.rn.f32 %f_acc23, %f_a2, %f_b7, %f_acc23;
    fma.rn.f32 %f_acc24, %f_a3, %f_b0, %f_acc24;
    fma.rn.f32 %f_acc25, %f_a3, %f_b1, %f_acc25;
    fma.rn.f32 %f_acc26, %f_a3, %f_b2, %f_acc26;
    fma.rn.f32 %f_acc27, %f_a3, %f_b3, %f_acc27;
    fma.rn.f32 %f_acc28, %f_a3, %f_b4, %f_acc28;
    fma.rn.f32 %f_acc29, %f_a3, %f_b5, %f_acc29;
    fma.rn.f32 %f_acc30, %f_a3, %f_b6, %f_acc30;
    fma.rn.f32 %f_acc31, %f_a3, %f_b7, %f_acc31;
    fma.rn.f32 %f_acc32, %f_a4, %f_b0, %f_acc32;
    fma.rn.f32 %f_acc33, %f_a4, %f_b1, %f_acc33;
    fma.rn.f32 %f_acc34, %f_a4, %f_b2, %f_acc34;
    fma.rn.f32 %f_acc35, %f_a4, %f_b3, %f_acc35;
    fma.rn.f32 %f_acc36, %f_a4, %f_b4, %f_acc36;
    fma.rn.f32 %f_acc37, %f_a4, %f_b5, %f_acc37;
    fma.rn.f32 %f_acc38, %f_a4, %f_b6, %f_acc38;
    fma.rn.f32 %f_acc39, %f_a4, %f_b7, %f_acc39;
    fma.rn.f32 %f_acc40, %f_a5, %f_b0, %f_acc40;
    fma.rn.f32 %f_acc41, %f_a5, %f_b1, %f_acc41;
    fma.rn.f32 %f_acc42, %f_a5, %f_b2, %f_acc42;
    fma.rn.f32 %f_acc43, %f_a5, %f_b3, %f_acc43;
    fma.rn.f32 %f_acc44, %f_a5, %f_b4, %f_acc44;
    fma.rn.f32 %f_acc45, %f_a5, %f_b5, %f_acc45;
    fma.rn.f32 %f_acc46, %f_a5, %f_b6, %f_acc46;
    fma.rn.f32 %f_acc47, %f_a5, %f_b7, %f_acc47;
    fma.rn.f32 %f_acc48, %f_a6, %f_b0, %f_acc48;
    fma.rn.f32 %f_acc49, %f_a6, %f_b1, %f_acc49;
    fma.rn.f32 %f_acc50, %f_a6, %f_b2, %f_acc50;
    fma.rn.f32 %f_acc51, %f_a6, %f_b3, %f_acc51;
    fma.rn.f32 %f_acc52, %f_a6, %f_b4, %f_acc52;
    fma.rn.f32 %f_acc53, %f_a6, %f_b5, %f_acc53;
    fma.rn.f32 %f_acc54, %f_a6, %f_b6, %f_acc54;
    fma.rn.f32 %f_acc55, %f_a6, %f_b7, %f_acc55;
    fma.rn.f32 %f_acc56, %f_a7, %f_b0, %f_acc56;
    fma.rn.f32 %f_acc57, %f_a7, %f_b1, %f_acc57;
    fma.rn.f32 %f_acc58, %f_a7, %f_b2, %f_acc58;
    fma.rn.f32 %f_acc59, %f_a7, %f_b3, %f_acc59;
    fma.rn.f32 %f_acc60, %f_a7, %f_b4, %f_acc60;
    fma.rn.f32 %f_acc61, %f_a7, %f_b5, %f_acc61;
    fma.rn.f32 %f_acc62, %f_a7, %f_b6, %f_acc62;
    fma.rn.f32 %f_acc63, %f_a7, %f_b7, %f_acc63;
    add.u32 %r_ab2, %r_ab2, 528;
    add.u32 %r_bb2, %r_bb2, 528;
    add.u32 %r_k, %r_k, 1;
    setp.lt.u32 %p1, %r_k, 8;
    @%p1 bra $mm_kloop;
    // ---- flip double-buffer stages and loop while K-tiles remain ----
    xor.b32 %r_buf, %r_buf, 4224;
    xor.b32 %r_nbuf, %r_nbuf, 4224;
    setp.lt.u32 %p1, %r_kt, %r_n;
    @%p1 bra $mm_outer;
$mm_store:
    // 8x8 sub-tile store: rows grow0..grow0+7, cols gcol0..gcol0+7.
    // N % 128 == 0 guarantees in-bounds, 16B-aligned rows, so st.global.v4.
    mul.lo.u32 %r_tmp, %r_grow0, %r_n;
    add.u32 %r_tmp, %r_tmp, %r_gcol0;
    mul.wide.u32 %rd_off, %r_tmp, 4;
    mul.wide.u32 %rd_rowstride, %r_n, 4;
    add.u64 %rd_addr, %rd_C, %rd_off;
    st.global.cs.v4.f32 [%rd_addr], {%f_acc0, %f_acc1, %f_acc2, %f_acc3};
    st.global.cs.v4.f32 [%rd_addr+16], {%f_acc4, %f_acc5, %f_acc6, %f_acc7};
    add.u64 %rd_addr, %rd_addr, %rd_rowstride;
    st.global.cs.v4.f32 [%rd_addr], {%f_acc8, %f_acc9, %f_acc10, %f_acc11};
    st.global.cs.v4.f32 [%rd_addr+16], {%f_acc12, %f_acc13, %f_acc14, %f_acc15};
    add.u64 %rd_addr, %rd_addr, %rd_rowstride;
    st.global.cs.v4.f32 [%rd_addr], {%f_acc16, %f_acc17, %f_acc18, %f_acc19};
    st.global.cs.v4.f32 [%rd_addr+16], {%f_acc20, %f_acc21, %f_acc22, %f_acc23};
